import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a journal thumbnail card with image texture, interactive hover lift, press-down click, and accent edge.
 * @param {Object} config - The PrismNode configuration.
 * @param {Object} ctx - Runtime context.
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // --- Card dimensions (derived from atlas source rect aspect 512/320 = 1.6) ---
  const cardWidth = 2.0;
  const cardHeight = cardWidth * (320 / 512); // ≈1.25

  // --- Geometry & Material ---
  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    color: '#ffffff', // placeholder until texture loads
    transparent: true,
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Accent edge (thin rim) — optional, for focus visual ---
  const edgeGeo = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04);
  const edgeMat = new MeshBasicNodeMaterial({
    color: config.intent?.visualSpec?.colors?.accent || '#ff2a38',
    transparent: true,
    opacity: 0, // hidden by default
    depthWrite: false,
    side: 1, // FrontSide
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.001; // slightly behind the card (so visible as border)
  group.add(edgeMesh);

  // --- Load texture (async) ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {
      // fallback: keep placeholder color
    });
  }

  // --- Interaction Handlers ---
  // Hover lift (rise-in): translate y upward
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: 0.15,
    duration: 0.5,
    ease: 'power3.out',
  }, 0);
  hoverTimeline.to(mesh.position, {
    z: 0.05, // slight forward lift
    duration: 0.5,
    ease: 'power3.out',
  }, 0);

  // Press-down scale
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  }, 0);

  // Accent edge on focus: fade edge in on pointerenter, out on pointerleave
  const edgeTimeline = gsap.timeline({ paused: true });
  edgeTimeline.to(edgeMat, {
    opacity: 0.7,
    duration: 0.3,
    ease: 'power2.out',
  }, 0);

  // Attach handlers to userData.handlers
  group.userData.handlers = {
    pointerenter: () => {
      hoverTimeline.play();
      edgeTimeline.play();
    },
    pointerleave: () => {
      hoverTimeline.reverse();
      edgeTimeline.reverse();
    },
    pointerdown: () => {
      pressTimeline.play();
    },
    pointerup: () => {
      pressTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-journal.select');
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    pressTimeline.kill();
    edgeTimeline.kill();
    geometry.dispose();
    material.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
